script:
const AMB = "#d9822b", RED = "#c62828", MUT = "#5d7880", TEAL = "#2a9d8f";
let E = {};
function seg(api, t, a, b) { return api.seg(t, a, b, "ease_in_out"); }
function moveArt(api, id, parent) { const a = api.$(id); parent.appendChild(a); return a; }
function tag(api, g, txt, x, y, color) { return R.text(api, g, txt, x, y, {anchor: "middle", size: 16, weight: 800, color, halo: false}); }
function tile(api, g) {
  api.el("rect", {x: 46, y: 182, width: 164, height: 200, rx: 20, fill: "#fff6ea", stroke: AMB, "stroke-width": 3, "stroke-dasharray": "9 7"}, g);
}

function setup(api) {
  const A = api.$("#art"), L = api.el("g", {id: "lab2"}, api.svg);
  A.appendChild(api.$("#organ"));
  E.s = [["63-year-old man", 190, MUT], ["Diarrhoea", 244, AMB], ["Fresh rectal blood", 298, RED], ["Loss of appetite", 352, AMB]].map(([tx, y, c]) => R.chip(api, L, tx, 52, y, c, {size: 19}));
  E.cOrg = [R.chip(api, L, "Rectum", 352, 164, MUT, {size: 18}), R.leader(api, L, 392, 178, 440, 230, MUT)];
  E.tum = R.lump(api, A, 408, 330, "tumour");
  E.glow = R.glow(api, A, 408, 330, {r: 42, color: "#e53935"});
  E.drip = R.drip(api, A, 418, 352, {fall: 90, r: 5.5, color: "#ff8a80"});
  E.cTum = [R.chip(api, L, "Tumour", 500, 290, RED, {size: 18}), R.leader(api, L, 520, 304, 440, 326, RED)];
  E.cAns = R.chip(api, L, "Rectal carcinoma", 46, 430, RED, {size: 21});
  E.cAge = R.chip(api, L, "Median age at diagnosis: 63", 46, 472, MUT, {size: 16});
}
function render(t, api) {
  E.s.forEach((c, i) => R.fade(api, c, t, 200 + i * 450, 600 + i * 450));
  R.fade(api, E.cOrg, t, 1500, 2000);
  E.tum.update(t, seg(api, t, 2400, 3800), 34, 26, 0.5 * seg(api, t, 3800, 4200));
  R.fade(api, E.cTum, t, 3000, 3500);
  E.drip.update(t, seg(api, t, 3600, 4000));
  E.glow.update(t, 0.8 * seg(api, t, 4700, 5300));
  R.fade(api, E.cAns, t, 4800, 5300);
  R.fade(api, E.cAge, t, 5400, 5900);
}
